"""Apply visually confirmed rests to a held-tool reconstruction candidate and score all frames."""
from pathlib import Path
import json,sys,numpy as np,trimesh,subprocess
from scipy.spatial.transform import Rotation,Slerp
r=Path(sys.argv[1]).resolve();rec=r/'reconstruction';cfg=json.loads((r/'episode-config.json').read_text());p=rec/'scene_motion_hand_guided_candidate.npz';a=np.load(p);out={k:a[k].copy() for k in a.files};raw=np.load(rec/'scene_motion_physical.npz');b=cfg['objects'].index('wooden_spoon');T=cfg['frames'];start=211 if cfg['episode']==32 else 289;anchor_start=252 if cfg['episode']==32 else 337;M=out['object_to_world'][:,b];O=raw['object_to_world'][:,b];mesh=trimesh.load(rec/'mesh_priors/wooden_spoon.ply',process=False);center=mesh.vertices.mean(0);anchors=O[anchor_start:];q=Rotation.from_matrix(anchors[:,:3,:3]).mean().as_matrix();position=np.median(np.einsum('tij,j->ti',anchors[:,:3,:3],center)+anchors[:,:3,3],axis=0)-q@center
for i in range(max(0,start-4),T):
 w=min(1.,(i-start+5)/5);M[i,:3,3]=(1-w)*M[i,:3,3]+w*position;M[i,:3,:3]=Slerp([0,1],Rotation.from_matrix([M[i,:3,:3],q]))([w])[0].as_matrix()
out['object_to_world'][:,b]=M;np.savez_compressed(p,**out);report=json.loads((rec/'hand-guided-tool-reconstruction-candidate.json').read_text());report['observed_static_tool_interval']=[start,T-1];report['static_anchor_frames']=[anchor_start,T-1];R=Rotation.from_matrix(M[:,:3,:3]);report['maximum_translation_step_m']=float(np.linalg.norm(np.diff(M[:,:3,3],axis=0),axis=1).max());report['maximum_orientation_step_rad']=float((R[:-1].inv()*R[1:]).magnitude().max());(rec/'hand-guided-tool-reconstruction-candidate.json').write_text(json.dumps(report,indent=2));s=(r/'scripts/assess_source_fidelity.py').read_text().replace("REC/'scene_motion_physical.npz'","REC/'scene_motion_hand_guided_candidate.npz'");script=r/'scripts/assess_hand_guided_candidate.py';script.write_text(s);print('Candidate continuity',report['maximum_translation_step_m'],report['maximum_orientation_step_rad'],flush=True);subprocess.run([str(r/'.venv-video/bin/python'),str(script),'--output','hand-guided-candidate','--overlay'],check=True)
